#!/usr/bin/env bash
# Ubuntu: run the headed Godot tests, each against a fresh simulator.
# Usage: scripts/run_headed_suite.sh [name ...]   (names: walk visual duel forestry food god war terrain ... launch tutorial ui conversation camera)
# GODOT defaults to ~/godot451/Godot_v4.5.1-stable_linux.x86_64. Shots go to HYBRID_SHOT_DIR (default docs/evidence/ubuntu).
# The laptop screen is smaller than 1920x1080, so any shot of that size fails here and needs the Windows machine.
set -u
HYB="$(cd "$(dirname "$0")/.." && pwd)"
REPO="$(dirname "$HYB")"
GODOT="${GODOT:-$HOME/godot451/Godot_v4.5.1-stable_linux.x86_64}"
export HYBRID_SHOT_DIR="${HYBRID_SHOT_DIR:-$HYB/docs/evidence/ubuntu}"
export DMB_RUNS="${DMB_RUNS:-/tmp/dmb_runs_headed}"  # saves and autosaves written by the headed scripts stay out of the owner's ~/dmb_runs/saves
mkdir -p "$HYBRID_SHOT_DIR"
declare -A SCRIPT=( [walk]=run_hybrid_walk.gd [visual]=run_hybrid_visual.gd [duel]=run_hybrid_duel.gd [forestry]=run_hybrid_forestry.gd [food]=run_hybrid_food.gd [god]=run_hybrid_god.gd [war]=run_hybrid_war.gd [terrain]=run_hybrid_terrain.gd [naval]=run_hybrid_naval.gd [playtest]=run_hybrid_playtest.gd [wizard]=run_hybrid_wizard.gd [mcv]=run_hybrid_mcv.gd [campaign]=run_hybrid_campaign.gd [campaign_dev]=run_hybrid_campaign.gd [industry]=run_hybrid_industry.gd [story]=run_hybrid_story.gd [outbreak]=run_hybrid_outbreak.gd [eras]=run_hybrid_eras.gd [autoplay]=run_hybrid_autoplay.gd [playtest2]=run_hybrid_playtest2.gd [inspector]=run_hybrid_god_inspector.gd [launch]=run_hybrid_launch.gd [tutorial]=run_hybrid_tutorial.gd [ui]=run_hybrid_ui.gd [conversation]=run_hybrid_conversation.gd [camera]=run_hybrid_camera.gd [apprentice_win]=run_hybrid_apprentice.gd [apprentice_lose]=run_hybrid_apprentice.gd )
declare -A MARK=( [walk]=HYBRID_WALK_OK [visual]=HYBRID_VISUAL_OK [duel]=HYBRID_DUEL_OK [forestry]=HYBRID_FORESTRY_OK [food]=HYBRID_FOOD_OK [god]=HYBRID_GOD_OK [war]=HYBRID_WAR_OK [terrain]=HYBRID_TERRAIN_OK [naval]=HYBRID_NAVAL_OK [playtest]=HYBRID_PLAYTEST_OK [wizard]=HYBRID_WIZARD_OK [mcv]=HYBRID_MCV_OK [campaign]=HYBRID_CAMPAIGN_OK [campaign_dev]=HYBRID_CAMPAIGN_OK [industry]=HYBRID_INDUSTRY_OK [story]=HYBRID_STORY_OK [outbreak]=HYBRID_OUTBREAK_OK [eras]=HYBRID_ERAS_OK [autoplay]=HYBRID_AUTOPLAY_OK [playtest2]=HYBRID_PLAYTEST2_OK [inspector]=HYBRID_GOD_INSPECTOR_OK [launch]=HYBRID_LAUNCH_OK [tutorial]=HYBRID_TUTORIAL_OK [ui]=HYBRID_UI_OK [conversation]=HYBRID_CONVERSATION_OK [camera]=HYBRID_CAMERA_OK [apprentice_win]=HYBRID_APPRENTICE_OK [apprentice_lose]=HYBRID_APPRENTICE_OK )
declare -A ENVX=( [forestry]="HYBRID_SPEED=4" [food]="HYBRID_SPEED=10" [war]="HYBRID_SPEED=60" [naval]="HYBRID_ALLOW_SPAWN=1" [playtest]="HYBRID_ALLOW_SPAWN=1" [wizard]="HYBRID_ALLOW_SPAWN=1" [mcv]="HYBRID_ALLOW_SPAWN=1" [campaign]="HYBRID_PROFILE=campaign HYBRID_EXPECT=campaign HYBRID_EXPLORE_MIN_MS=99999999 HYBRID_EXPLORE_FALLBACK_MS=99999999" [campaign_dev]="HYBRID_PROFILE=developer HYBRID_EXPECT=developer HYBRID_DRAFT_MS=2000" [industry]="HYBRID_PROFILE=developer HYBRID_FIXTURE=modern_industry HYBRID_ALLOW_SPAWN=1" [story]="HYBRID_PROFILE=developer HYBRID_FIXTURE=story" [outbreak]="HYBRID_PROFILE=developer HYBRID_FIXTURE=outbreak" [eras]="HYBRID_PROFILE=developer HYBRID_ERA_MS=20000 HYBRID_ERA_VP=99" [autoplay]="HYBRID_PROFILE=developer HYBRID_START_SPEED=16 HYBRID_AI_POLICY=mixed HYBRID_SEED=507" [playtest2]="HYBRID_PROFILE=developer HYBRID_FIXTURE=story" [inspector]="HYBRID_PROFILE=developer HYBRID_CARDSET=v2" [launch]="HYBRID_PROFILE=campaign HYBRID_EXPECT=campaign HYBRID_AUTOSAVE_SECONDS=5 HYBRID_EXPLORE_MIN_MS=99999999 HYBRID_EXPLORE_FALLBACK_MS=99999999" [tutorial]="HYBRID_PROFILE=campaign HYBRID_EXPECT=campaign HYBRID_EXPLORE_MIN_MS=99999999 HYBRID_EXPLORE_FALLBACK_MS=99999999" [ui]="HYBRID_PROFILE=campaign HYBRID_EXPECT=campaign HYBRID_EXPLORE_MIN_MS=99999999 HYBRID_EXPLORE_FALLBACK_MS=99999999" [conversation]="HYBRID_PROFILE=developer HYBRID_EXPECT=developer" [camera]="HYBRID_PROFILE=campaign HYBRID_EXPECT=campaign HYBRID_EXPLORE_MIN_MS=99999999 HYBRID_EXPLORE_FALLBACK_MS=99999999" [apprentice_win]="HYBRID_PROFILE=campaign HYBRID_EXPECT=campaign HYBRID_EXPLORE_MIN_MS=15000 HYBRID_EXPLORE_FALLBACK_MS=40000 HYBRID_AFTERMATH_FALLBACK_MS=30000 HYBRID_APPRENTICE_ENDING=win" [apprentice_lose]="HYBRID_PROFILE=campaign HYBRID_EXPECT=campaign HYBRID_EXPLORE_MIN_MS=15000 HYBRID_EXPLORE_FALLBACK_MS=40000 HYBRID_AFTERMATH_FALLBACK_MS=30000 HYBRID_APPRENTICE_ENDING=lose" )
names=("$@"); [ ${#names[@]} -eq 0 ] && names=(walk visual duel forestry food god war terrain naval playtest wizard mcv campaign campaign_dev industry story outbreak eras)
failed=()
for n in "${names[@]}"; do
  # a free port every time (a simulator left behind by an interrupted run must never be reused: its clock would be advanced)
  port=$(python3 -c "import socket; s=socket.socket(); s.bind(('127.0.0.1',0)); print(s.getsockname()[1])")
  (cd "$HYB" && env HYBRID_PROFILE=${HYBRID_PROFILE:-test_showcase} HYBRID_SIM_PORT=$port ${ENVX[$n]:-} python3 -u -m wizard_rts.server >/tmp/hybrid_sim_$port.log 2>&1 & echo $! > /tmp/hybrid_sim_$port.pid)
  for _i in $(seq 1 60); do grep -q HYBRID_SIM_READY /tmp/hybrid_sim_$port.log 2>/dev/null && break; sleep 1; done
  out=$(env HYBRID_SIM_PORT=$port ${ENVX[$n]:-} timeout "${TIMEOUT:-1700}" "$GODOT" --path "$REPO/godot_project" --rendering-method forward_plus --script "res://client/tests/${SCRIPT[$n]}" 2>&1)
  kill "$(cat /tmp/hybrid_sim_$port.pid)" 2>/dev/null
  if echo "$out" | grep -q "${MARK[$n]}"; then echo "PASS $n"; else echo "FAIL $n"; echo "$out" | grep -E "FAIL|ERROR|SCRIPT" | head -5 | sed 's/^/  /'; failed+=("$n"); fi
done
[ ${#failed[@]} -gt 0 ] && { echo "HEADED_SUITE_FAILED ${failed[*]}"; exit 1; }
echo HEADED_SUITE_OK
